agents = {}
for f in files:
    if not os.path.exists(f):
        continue
    try:
        with open(f) as fh:
            d = json.load(fh)
    except:
        continue
    rows = d.get('rows') or d.get('result', {}).get('rows', [])
    for r in rows:
        if r.get('_hatch_db_row_omitted'):
            continue
        aid = r.get('agent_id')
        if not aid or 'item_json' not in r:
            continue
        try:
            msg = json.loads(r['item_json'])
        except:
            continue
        agents.setdefault(aid, []).append((r['seq'], msg))

outdir = '/home/hatch/workspace/your_files/agent_exports'
os.makedirs(outdir, exist_ok=True)

total = 0
index = []
for aid in sorted(agents.keys()):
    items = agents[aid]
    items.sort(key=lambda x: x[0])
    seen = set()
    uniq = []
    for seq, msg in items:
        if seq not in seen:
            seen.add(seq)
            uniq.append({"seq": seq, "message": msg})
    # Merge with existing file if present
    short = aid[:8]
    path = f"{outdir}/agent-{short}.jsonl"
    existing = []
    if os.path.exists(path):
        with open(path) as fh:
            for line in fh:
                try:
                    it = json.loads(line)
                    existing.append((it['seq'], it['message']))
                except:
                    pass
    combined = {s: m for s, m in existing}
    for it in uniq:
        combined[it['seq']] = it['message']
    final = [{"seq": s, "message": combined[s]} for s in sorted(combined.keys())]
    total += len(final)
    with open(path, 'w') as fh:
        for it in final:
            fh.write(json.dumps(it, ensure_ascii=False) + '\n')
    label = ""
    for it in final:
        m = it['message']
        if m.get('type') == 'message' and m.get('role') == 'user':
            label = m.get('text', '')[:80].replace('\n', ' ')
            break
        if m.get('type') == 'message_parts':
            for p in m.get('parts', []):
                if p.get('type') == 'text' and '[Subagent Task]' in p.get('text', ''):
                    label = p['text'].split('[Subagent Task]')[-1][:80].replace('\n', ' ')
                    break
            if label:
                break
    index.append({"agent_id": aid, "short": short, "count": len(final), "file": f"agent-{short}.jsonl", "label": label})

with open(f"{outdir}/INDEX.md", 'w') as fh:
